// 处理RSS数据
var items = $input.all();
var results = [];
var mbtiKeywords = ['mbti', 'infj', 'infp', 'intj', 'intp', 'enfj', 'enfp', 'entj', 'entp', '性格', '内向', '外向', '社恐', '社交', '心理', 'i人', 'e人', '人格', '测试', '年轻人', '消费', '生活'];

for (var i = 0; i < Math.min(5, items.length); i++) {
  var item = items[i].json;
  var title = item.title || '';
  var link = item.link || '';
  var content = item.contentSnippet || item.content || title;

  var titleLower = title.toLowerCase();
  var isRelevant = false;
  for (var k = 0; k < mbtiKeywords.length; k++) {
    if (titleLower.indexOf(mbtiKeywords[k]) !== -1) {
      isRelevant = true;
      break;
    }
  }

  results.push({
    json: {
      index: i,
      title: title,
      link: link,
      content: content.substring(0, 500),
      source: '知乎热榜',
      score: isRelevant ? 8 : 5,
      upvotes: 10 - i,
      isRelevant: isRelevant,
      created: new Date().toISOString()
    }
  });
}
return results;

// 构建Notion请求体
var d = $json;
var body = {
  parent: { database_id: '2d87fa67-a9af-81b9-9b07-cde5013942b4' },
  properties: {
    '标题': { title: [{ text: { content: d.title || '无标题' } }] },
    '来源': { select: { name: d.source || '热榜' } },
    '原文链接': { url: d.link || 'https://example.com' },
    '原文摘要': { rich_text: [{ text: { content: (d.content || '').substring(0, 500) } }] },
    '热度评分': { number: d.score || 5 },
    '契合度': { number: d.score || 5 },
    '创作角度': { rich_text: [{ text: { content: '' } }] },
    '使用次数': { number: 0 },
    '状态': { select: { name: '待评估' } }
  }
};
return [{ json: { notionBody: JSON.stringify(body), originalData: d } }];

// 生成推荐报告
var allItems = $input.first().json.data || [];
var summary = '## MBTI素材采集报告\n\n';
summary += '共采集 ' + allItems.length + ' 条内容\n\n';

// 分离相关和不相关内容
var relevant = [];
var other = [];
for (var i = 0; i < allItems.length; i++) {
  var item = allItems[i].originalData;
  if (item && item.isRelevant) {
    relevant.push(item);
  } else if (item) {
    other.push(item);
  }
}

if (relevant.length > 0) {
  summary += '### MBTI相关内容 (' + relevant.length + '条)\n\n';
  for (var i = 0; i < relevant.length; i++) {
    var item = relevant[i];
    summary += (i + 1) + '. **' + item.title + '**\n';
    if (item.link) summary += '   链接: ' + item.link + '\n';
    summary += '\n';
  }
}

if (other.length > 0) {
  summary += '### 其他热门内容 (' + other.length + '条)\n\n';
  for (var i = 0; i < Math.min(3, other.length); i++) {
    var item = other[i];
    summary += (i + 1) + '. ' + item.title + '\n';
  }
}

summary += '\n### 创作建议\n';
summary += '- MBTI相关内容可直接改编\n';
summary += '- 热门话题可结合MBTI角度创作\n';

return [{ json: { report: summary, relevantCount: relevant.length, totalCount: allItems.length } }];
